      "tipo": "DrawCalls",
      "causa_raiz": "Número excessivo de Draw Calls por frame (atingindo pico de 28.027 calls contra o limite orçamentário de 2.579), resultando em gargalo severo na GPU (projetado em até 56.67ms). Isso ocorre pela ausência de combinação de malhas (Mesh Batching) e GPU Instancing em objetos repetidos da cena.",
      "codigo_refatorado": "using UnityEngine;

[RequireComponent(typeof(MeshFilter))]
[RequireComponent(typeof(MeshRenderer))]
public class RuntimeMeshCombiner : MonoBehaviour
{
    [SerializeField] private bool disableOriginalRenderers = true;

    private void Start()
    {
        CombineMeshes();
    }

    public void CombineMeshes()
    {
        MeshFilter[] filters = GetComponentsInChildren<MeshFilter>();
        CombineInstance[] combine = new CombineInstance[filters.Length];
        Material commonMaterial = null;
        int combineIndex = 0;

        for (int i = 0; i < filters.Length; i++)
        {
            if (filters[i].gameObject == this.gameObject || filters[i].sharedMesh == null) continue;

            MeshRenderer renderer = filters[i].GetComponent<MeshRenderer>();
            if (renderer != null)
            {
                if (commonMaterial == null)
                {
                    commonMaterial = renderer.sharedMaterial;
                }
                if (disableOriginalRenderers)
                {
                    renderer.enabled = false;
                }
            }

            combine[combineIndex].mesh = filters[i].sharedMesh;
            combine[combineIndex].transform = transform.worldToLocalMatrix * filters[i].transform.localToWorldMatrix;
            combineIndex++;
        }

        System.Array.Resize(ref combine, combineIndex);

        Mesh combinedMesh = new Mesh();
        combinedMesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
        combinedMesh.CombineMeshes(combine, true, true);

        GetComponent<MeshFilter>().sharedMesh = combinedMesh;
        if (commonMaterial != null)
        {
            GetComponent<MeshRenderer>().sharedMaterial = commonMaterial;
        }
    }
}",
      "explicacao_didatica": "Um Draw Call é uma ordem dada à GPU para desenhar um objeto na tela. Desenhar 28.000 objetos individualmente gera um custo imenso de comunicação. O código acima consolida múltiplos objetos menores que compartilham o mesmo material em uma única malha (Mesh) unificada, permitindo que a placa de vídeo desenhe tudo em apenas uma única chamada."
    }
  ],
  "dicas_level_design": "1. Ative a opção 'Enable GPU Instancing' em todos os Materiais aplicados a objetos repetidos (árvores, pedras, adereços do cenário).
2. Marque objetos estáticos do cenário como 'Batching Static' no Inspector para que a Unity aplique Static Batching em tempo de compilação.
3. Configure o Occlusion Culling (Window > Rendering > Occlusion Culling) para evitar a renderização de objetos escondidos atrás de paredes ou montanhas.
4. Crie Texture Atlases para agrupar várias texturas em uma só, permitindo que objetos diferentes compartilhem o mesmo material e sejam agrupados em lote.
5. Aplique LOD Groups (Level of Detail) em modelos 3D complexos para simplificar a geometria e desligar renderizadores em longas distâncias."
}

